import { seasonMoment, playCareerMoment, POSITIONS, ATTRS, ORIGINS, PERSONALITIES, STYLES, DREAMS, newCareer, getClub, getCountry, migrateCareer, careerYear, draftChoices, acceptDraft, rerollDraft, choosePreparation, academyOffers, signAcademy, advanceSeason, simulatedStandings, eventInfo, resolveEvent, finishEvent, autoResolveEvent, chooseTransfer, chooseSeasonPlan, SEASON_PLANS, chooseSeasonAgenda, openAgentMarket, askAgentForMore, retireFromMarket, simulateToRetirement, totals } from './engine.mjs';
const ROOT=document.getElementById('app');
const STORE='rascenso-save-v2',OLD='carrera-mundial-demo-v1';
const h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=x=>Number(x||0).toLocaleString('es-CL');
const short=x=>String(x||'').length>20?String(x).slice(0,18)+'…':x;
const pick=(arr,id)=>arr.find(x=>x.id===id)?.name||'—';
const countryName=c=>getCountry(c)?.name||c;
let state=null,tab='carrera',wizard=0,showHistory=false,message='',showNew=false,rightTab='standings';
const skillUI={zone:null,started:0};
const timingAt=elapsed=>{const phase=((elapsed%2400)+2400)%2400/1200;return Math.max(0,Math.min(100,Math.round((phase<=1?phase:2-phase)*100)));};

const draft={name:'',country:'CL',age:'17',position:'DC',number:'9',foot:'Derecha',city:'',origin:'barrio',personality:'disciplinado',style:'equilibrado',dream:'seleccion',fanClubId:'',mode:'Clásico',environment:'sin_contactos',publicImage:'reservado',riskProfile:'calculador',developmentPath:'tecnica'};
function load(){
 for(const key of [STORE,STORE+'-backup',OLD]){
  try{const raw=localStorage.getItem(key);if(!raw)continue;const recovered=migrateCareer(JSON.parse(raw));if(recovered){state=recovered;if(key===STORE+'-backup')message='Se recuperó un respaldo de tu partida.';break;}}catch{continue;}
 }
}
load();
function save(){
 try{
  if(!state)return true;
  const previous=localStorage.getItem(STORE),next=JSON.stringify(state);
  if(previous&&previous!==next)localStorage.setItem(STORE+'-backup',previous);
  localStorage.setItem(STORE,next);
  return true;
 }catch{message='No fue posible guardar la partida. Exporta una copia desde el menú.';return false;}
}
function mutate(s){if(!s||s===state)return;state=s;save();tab='carrera';render();}
function button(label,action,cls='main',more=''){return `<button type="button" class="action ${cls}" data-action="${action}" ${more}>${label}</button>`;}
const opt=(value,label,active)=>`<option value="${h(value)}" ${active===value?'selected':''}>${h(label)}</option>`;
function select(label,name,items,value){return `<label class="field"><span>${label}</span><select name="${name}">${items.map(([v,l])=>opt(String(v),l,String(value))).join('')}</select></label>`;}
function branding(){return `<a class="brand brand-13" href="./" aria-label="RASCENSO"><img src="./assets/brand/rascenso-wordmark.png" alt="RASCENSO · Del barrio a la historia" width="300" height="75"></a>`;}
function header(){return `<header class="site-head">${branding()}<nav class="main-nav">${state?['carrera','historial','mundo'].map(t=>`<button class="navtab ${tab===t?'selected':''}" data-action="nav" data-tab="${t}">${{carrera:'Mi carrera',historial:'Historial',mundo:'Mundo'}[t]}</button>`).join(''):'<span class="navtab selected">Tu historia empieza hoy</span>'}</nav><div class="head-controls"><span class="build">ALFA 1.6 · JUGADAS VIVAS</span>${state?`<span class="head-name">${h(state.name)}</span>${button('⋯','tools','ghost')}`:`<span class="live"><i></i> MODO CARRERA</span>`}</div></header>`;}
function shell(content,extra=''){ROOT.innerHTML=`<div class="app-shell">${header()}<main class="view ${state?'playing':''}">${content}</main><footer class="site-foot"><span>RASCENSO · Una creación de Ragamoofi</span><span>${CATALOG_COUNT} clubes disponibles · 13 ligas iniciales verificadas · copas globales con formato simplificado</span></footer>${extra}</div>${message?`<div class="notification" role="alert">${h(message)}</div>`:''}`;}
function featureIcon(name){return {glory:'★',home:'⌂',academy:'⚑',form:'◉',tactic:'♟',news:'◎',league:'▥'}[name]||'✦';}
function createSteps(){return ['Identidad','Raíces','Futbolista','Mentalidad','Sueños','Resumen'].map((s,i)=>`<button type="button" class="creation-step ${wizard===i?'active':wizard>i?'past':''}" data-action="step" data-index="${i}"><span>0${i+1}</span>${s}</button>`).join('');}
function textInput(name,label,placeholder='',extra=''){return `<label class="field"><span>${label}</span><input name="${name}" value="${h(draft[name])}" placeholder="${h(placeholder)}" ${extra}></label>`;}
function choiceGroup(label,list,name){return `<div class="select-group"><h3>${label}</h3><div class="choice-tiles">${list.map(x=>`<label class="choice-tile ${draft[name]===x.id?'chosen':''}"><input type="radio" name="${name}" value="${x.id}" ${draft[name]===x.id?'checked':''}><strong>${h(x.name)}</strong><small>${h(x.description)}</small></label>`).join('')}</div></div>`;}
function creator(){
 let section='';
 if(wizard===0)section=`<div class="section-label">CAPÍTULO I · TU PRIMERA CAMISETA</div><h1>Todo comienza <em>con un nombre.</em></h1><p class="section-intro">Elige tu identidad y el país donde empezarás a buscar tu primera oportunidad profesional.</p><div class="fields-grid">${textInput('name','Nombre del futbolista','Ej.: Oscar Sariego','required maxlength="44"')}${select('Nacionalidad','country',COUNTRIES.map(c=>[c.code,c.name]),draft.country)}${select('Posición','position',POSITIONS,draft.position)}${select('Edad de inicio','age',[16,17,18,19].map(x=>[x,`${x} años`]),draft.age)}${textInput('number','Dorsal','9','type="number" min="1" max="99"')}${select('Pierna hábil','foot',[['Derecha','Derecha'],['Izquierda','Izquierda']],draft.foot)}</div>`;
 if(wizard===1)section=`<div class="section-label">CAPÍTULO II · DONDE NACE EL TALENTO</div><h1>Los grandes caminos <em>tienen un origen.</em></h1><p class="section-intro">No son preguntas de roleo: estos antecedentes afectan tu adaptación al fútbol profesional.</p>${textInput('city','Ciudad de origen','Ej.: Santiago, La Cisterna','maxlength="40"')}${choiceGroup('Tu formación',ORIGINS,'origin')}${choiceGroup('Tu entorno',ENVIRONMENTS,'environment')}`;
 if(wizard===2)section=`<div class="section-label">CAPÍTULO III · IDENTIDAD DE JUEGO</div><h1>¿Qué futbolista <em>quieres ser?</em></h1><p class="section-intro">Una personalidad y un estilo. Las decisiones deportivas irán construyendo tu reputación.</p>${choiceGroup('Personalidad',PERSONALITIES,'personality')}${choiceGroup('Estilo en la cancha',STYLES,'style')}${choiceGroup('Tu desarrollo',DEVELOPMENT_PATHS,'developmentPath')}`;
 if(wizard===3)section=`<div class="section-label">CAPÍTULO IV · TU MENTALIDAD</div><h1>El fútbol también <em>se juega fuera.</em></h1><p class="section-intro">Estas decisiones cambian tu reputación y tu relación con los clubes.</p>${choiceGroup('Tu imagen pública',PUBLIC_IMAGES,'publicImage')}${choiceGroup('Cómo decides tu futuro',RISK_PROFILES,'riskProfile')}`;
 if(wizard===4){section=`<div class="section-label">CAPÍTULO V · TU AMBICIÓN</div><h1>Hay camisetas <em>que se sueñan.</em></h1><p class="section-intro">El equipo del que eres hincha es opcional: no fuerza ofertas, pero la carrera recordará ese vínculo.</p><div class="fields-grid"><label class="field"><span>Club del que eres hincha · opcional</span><select name="fanClubId"><option value="">Ninguno · seguir sin elegir</option>${COUNTRIES.map(c=>`<optgroup label="${h(c.name)}">${c.clubs.filter(x=>!x.inactive).map(x=>opt(x.id,x.name,draft.fanClubId)).join('')}</optgroup>`).join('')}</select></label>${select('Modo del draft','mode',[['Clásico','Clásico · Ver atributos'],['Purista','Purista · Valores ocultos']],draft.mode)}</div>${choiceGroup('Sueño deportivo',DREAMS,'dream')}`;}
 if(wizard===5)section=`<div class="section-label">CAPÍTULO VI · PERFIL PREVIO</div><h1>Tu carrera <em>comienza acá.</em></h1><p class="section-intro">Tus decisiones no garantizan el éxito: cambian las oportunidades y los riesgos.</p><div class="summary-traits">${[['Procedencia',draft.city||'Tu ciudad'],['Formación',pick(ORIGINS,draft.origin)],['Entorno',pick(ENVIRONMENTS,draft.environment)],['Carácter',pick(PERSONALITIES,draft.personality)],['Desarrollo',pick(DEVELOPMENT_PATHS,draft.developmentPath)],['Imagen',pick(PUBLIC_IMAGES,draft.publicImage)],['Riesgo',pick(RISK_PROFILES,draft.riskProfile)],['Objetivo',pick(DREAMS,draft.dream)]].map(([k,v])=>`<div><small>${h(k)}</small><strong>${h(v)}</strong></div>`).join('')}</div>`;
 const club=getClub(draft.fanClubId);
 const aside=`<div class="recruit-poster"><div class="poster-top"><span>RASCENSO / TALENTO</span><span>2026</span></div><div class="poster-shape">${h((draft.name||'R').slice(0,1).toUpperCase())}</div><strong>${h(draft.name||'TU NOMBRE')}</strong><p>${flag(draft.country)} ${h(countryName(draft.country))} · ${h(POSITIONS.find(p=>p[0]===draft.position)?.[1]||'Delantero centro')}</p><div class="poster-attributes"><span>EDAD <b>${h(draft.age)}</b></span><span>DORSAL <b>#${h(draft.number)}</b></span></div>${club?`<div class="poster-fan">${badge(club)} <span>Hincha de <b>${h(club.name)}</b></span></div>`:'<div class="poster-fan">✦ Escribe tu propia historia</div>'}</div><div class="poster-bottom"><strong>EL PRIMER DÍA</strong><p>De aquí en adelante, los goles, los clubes, las oportunidades y las decisiones construyen tu legado.</p></div>`;
 shell(`<div class="creation-layout"><section class="creation-panel"><div class="creation-tabs">${createSteps()}</div><form id="creation-form" novalidate><div class="creation-content">${section}</div><div class="creation-actions">${wizard?button('← Atrás','creator-prev','secondary'):''}<span class="step-count">PASO ${wizard+1} DE 6</span>${button(wizard===5?'Comenzar mi carrera ↗':'Continuar →',wizard===5?'create':'creator-next')}</div></form></section><aside class="creation-aside">${aside}</aside></div>`);
}
function playerCard(){const club=getClub(state.clubId),country=getCountry(state.country),p=state;return `<aside class="left-rail"><div class="profile-card player-tier-${p.ovr>=83?'elite':p.ovr>=75?'gold':p.ovr>=65?'silver':'bronze'}"><div class="player-label">TARJETA DEL FUTBOLISTA <span>${h(p.position)} · #${h(p.number)}</span></div><div class="player-overall"><strong>${p.ovr??'—'}</strong><span>MEDIA</span></div><div class="card-crest">${club?badge(club,'large'):'<span class="card-free">⚽</span>'}</div><h2>${h(p.name)}</h2><p>${flag(p.country)} ${h(country?.name)} · ${h(p.position)}</p><div class="player-line"><span>${p.age} años</span><span>${h(p.foot)}</span></div><div class="player-economy"><div><small>VALOR DE MERCADO</small><strong>${annualSalaryLabel(marketValueEUR(p,club))}</strong></div><div><small>SUELDO MENSUAL</small><strong>${annualSalaryLabel(contractSnapshot(p).monthly)}</strong></div><div><small>CONTRATO</small><strong>${contractSnapshot(p).remaining?`${contractSnapshot(p).remaining} año(s) · ${contractSnapshot(p).expires}`:'Sin renovación'}</strong></div></div><div class="player-club">${club?badge(club,'large'):'<span class="unassigned">⚽</span>'}<div><small>CLUB ACTUAL</small><strong>${h(club?.name||'Sin contrato')}</strong></div></div></div><div class="rail-panel"><div class="rail-heading"><span>MI TEMPORADA</span><b>${h(state.lastSeason?.year||careerYear(state))}</b></div><div class="stat-row"><div><strong>${n(state.lastSeason?.matches||0)}</strong><small>PARTIDOS</small></div><div><strong>${n(state.lastSeason?.goals||0)}</strong><small>GOLES</small></div><div><strong>${n(state.lastSeason?.assists||0)}</strong><small>ASIST.</small></div></div><div class="rail-meter"><span>Confianza del entrenador <b>${n(state.coachTrust??50)}%</b></span><div><i style="width:${Math.min(100,state.coachTrust??50)}%"></i></div></div><div class="rail-meter"><span>Moral del jugador <b>${n(state.morale??70)}%</b></span><div><i style="width:${Math.min(100,state.morale??70)}%"></i></div></div></div><div class="rail-panel facts"><div class="rail-heading"><span>PERFIL</span><span class="ornament">✦</span></div><div><span>Origen</span><b>${h(pick(ORIGINS,state.origin))}</b></div><div><span>Estilo</span><b>${h(pick(STYLES,state.style))}</b></div><div><span>Identidad</span><b>${h((state.footballDNA||archetypeFor(state)).name)}</b></div><div><span>Perfil público</span><b>${h(pick(PUBLIC_IMAGES,state.publicImage))}</b></div><div><span>Club de hincha</span><b>${h(state.fanClubId?getClub(state.fanClubId)?.name:'Sin elegir')}</b></div><div><span>Contrato</span><b>${state.contract?.ends?Math.max(0,state.contract.ends-careerYear(state)):state.contract?.yearsLeft??'—'} años</b></div><div><span>Salario anual estimado</span><b>${annualSalaryLabel(state.contract?.salary)}</b></div><div><span>Ingresos de carrera</span><b>${annualSalaryLabel(state.careerEarnings||0)}</b></div></div></aside>`;}
function table(){const club=getClub(state.clubId),competition=getCompetitionForCareer(state),allRows=simulatedStandings(state),historic=[...state.history].reverse().find(x=>x.clubId===state.clubId&&Array.isArray(x.table)),hasSeason=!!historic,rows=hasSeason?allRows:[];
 let body='';
 if(rows.length){body=`<div class="table-caption">${h([...state.history].reverse().find(x=>x.clubId===state.clubId&&x.table)?.leagueName||club?.league||'Liga')} · ${[...state.history].reverse().find(x=>x.clubId===state.clubId&&x.table)?.year||'—'}</div><div class="table-head"><span>POS · CLUB</span><span>PJ</span><span>DG</span><span>PTS</span></div><div class="standings-list">${rows.map(x=>`<div class="standing-row ${x.isPlayer?'mine':''}"><span class="standing-team"><b class="rank">${x.position}</b>${badge(x)}<span>${h(short(x.name))}</span></span><span>${x.played}</span><span>${x.gd>0?'+':''}${x.gd}</span><strong>${x.points}</strong></div>`).join('')}</div>`;}
 else {const contenders=leagueParticipants(club?.countryCode||state.country,club?.id,state).sort((a,b)=>b.level-a.level);body=`<div class="table-caption">${competition?.verified?'Participantes de '+h(competition.season)+' · '+h(competition.name):'Circuito de referencia · participantes aún no verificados'} · nivel estimado</div><div class="table-head"><span>CLUB</span><span>NIVEL</span></div><div class="standings-list prep">${contenders.map((x,i)=>`<div class="standing-row"><span class="standing-team"><b class="rank">${i+1}</b>${badge(x)}<span>${h(short(x.name))}</span></span><strong>${x.level}</strong></div>`).join('')}</div>`;}
 const lastMatches=(historic?.playerMatches||[]).slice(-11).reverse();
 const gameHtml=`<div class="standings-list match-list">${lastMatches.length?lastMatches.map(g=>`<div class="fixture-item"><small>FECHA ${g.round} · ${g.played?g.minutes+' MIN':'SIN MINUTOS'}</small><div>${badge(g.home,'tiny')}<span>${h(short(getClub(g.home)?.name||''))}</span><b>${h(g.score)}</b><span>${h(short(getClub(g.away)?.name||''))}</span>${badge(g.away,'tiny')}</div>${g.played?`<small>${g.goals} GOL(ES) · ${g.assists} ASISTENCIA(S)</small>`:''}</div>`).join(''):'<div class="table-caption">Simula una temporada para ver tus partidos.</div>'}</div>`;
 return `<aside class="right-rail"><section class="table-card"><div class="side-top"><span class="section-label">EL CAMPEONATO</span>${flag(club?.countryCode||state.country)}</div><h2>Tabla de posiciones</h2><div class="competition-heading"><div class="league-brand">${competition?.id&&competitionLogo(competition.id)?`<img src="${competitionLogo(competition.id)}" loading="lazy" alt="" onerror="this.remove()">`:''}<b>${h(competition?.name||'Liga de referencia')}</b></div><small>${competition?.verified?'PARTICIPANTES 2026 VERIFICADOS':'FORMATO DE REFERENCIA · NO OFICIAL'}</small></div><div class="right-tabs"><button class="${rightTab==='standings'?'active':''}" data-action="right-tab" data-id="standings">CLASIFICACIÓN</button><button class="${rightTab==='matches'?'active':''}" data-action="right-tab" data-id="matches">MIS PARTIDOS</button></div>${rightTab==='matches'?gameHtml:body}</section><section class="news-card"><span class="section-label">TU CARRERA EN CIFRAS</span><div class="career-kpis">${[['Temporadas',state.history.length],['Títulos',state.trophies.length],['Clubes',new Set(state.history.map(x=>x.clubId)).size||1]].map(([k,v])=>`<div><b>${n(v)}</b><small>${k}</small></div>`).join('')}</div></section>${trophyGallery()}</aside>`;
}
function trophyGallery(){const raw=state.trophyRecords?.length?state.trophyRecords:(state.trophies||[]).map((x,i)=>({title:String(x),year:state.history?.[i]?.year||'—',clubId:state.history?.[i]?.clubId||state.clubId,kind:'league'}));const ordered=[...raw].sort((a,b)=>(Number(b.year)||0)-(Number(a.year)||0));return `<section class="trophy-showcase"><div class="rail-heading"><span>VITRINA DE TÍTULOS</span><strong>${ordered.length}</strong></div><div class="trophy-grid">${ordered.length?ordered.slice(0,18).map((t,i)=>{const kind=/mundial|world|selecci[oó]n/i.test(t.title)?'world':/libertadores|champions/i.test(t.title)?'continental':/copa/i.test(t.title)?'cup':'league';return `<div class="trophy-unit" title="${h(`${t.title} · ${t.year} · ${getClub(t.clubId)?.name||''}`)}"><img src="${trophyImage(t)}" onerror="this.src='./assets/trophies/${kind}.png'" alt="Trofeo ilustrativo"><span>${h(t.year)}</span></div>`}).join(''):'<p>Tu primer título tendrá su lugar acá.</p>'}</div></section>`;}
function frame(center){const club=getClub(state.clubId);return `<div class="playing-layout">${playerCard()}<div class="center-rail"><div class="career-heading"><div><span class="section-label">TEMPORADA ${h(careerYear(state))} · ${flag(club?.countryCode||state.country)} ${h(getCompetitionForCareer(state)?.name||club?.country||countryName(state.country))}</span><h1>${h(club?.name||'Tu carrera comienza aquí')}</h1></div><span class="year-pill">${h(state.age)} AÑOS · ${h(state.position)}</span></div>${center}</div>${table()}</div>`;}
function seasonMomentPanel(){
 const m=seasonMoment(state),outcome=state.clutchMoment;
 if(!m&&!outcome)return '';
 const v=outcome||m,role=MOMENT_NAMES[v.type]||'Jugada clave';
 const description=v.type==='penal'?'El balón está en el punto penal: elegí destino y golpeá en el instante preciso.':v.type==='libre'?'El tiro libre exige dirección y precisión para superar la barrera.':v.type==='pase'?'Un compañero arranca entre líneas. Elegí el pase y ejecutalo antes de que se cierre el hueco.':v.type==='corte'?'El delantero rival prepara el regate. Anticipá su dirección y llegá justo al balón.':'Quedaste mano a mano. Elegí dónde cubrir y reaccioná en el momento preciso.';
 const pitch=`<div class="clutch-goal" aria-label="Arco con tres zonas"><div class="clutch-net"><span></span><span></span><span></span></div>${outcome?`<div class="clutch-ball" style="left:${16.66+outcome.zone*33.33}%">⚽</div>`:''}</div>`;
 const target=timingTarget(v),selected=skillUI.zone;
 const meter=!outcome&&selected!==null?`<div class="clutch-timing"><div class="clutch-timing-top"><strong>2 · DETENÉ EL MEDIDOR</strong><small>${h(ZONES[selected])} · buscá la franja dorada</small></div><div class="clutch-meter-track" aria-label="Medidor móvil de precisión"><span class="clutch-perfect-window" style="left:${target-9}%"></span><span class="clutch-needle"></span></div><div class="clutch-timing-actions"><button data-action="clutch-cancel" type="button">Cambiar dirección</button><button class="clutch-hit-button" data-action="clutch-stop" type="button">⚡ EJECUTAR JUGADA <small>o barra espaciadora</small></button></div></div>`:'';
 return `<section class="clutch-stage"><div class="clutch-meta"><span>⚡ MOMENTO DECISIVO · ${h(v.tag)}</span><b>FECHA ${v.round}</b></div><div class="clutch-fixture"><span>${h(v.club)} <b>VS</b> ${h(v.rival)}</span>${v.classic?'<strong>CLÁSICO</strong>':''}</div><h3>${h(role)}</h3><p>${h(description)}</p>${pitch}${outcome?`<div class="clutch-result ${outcome.success?'is-good':'is-bad'}"><strong>${outcome.success?'¡Acción conseguida!':'La jugada no salió como querías.'}</strong><small>${outcome.timing!==null&&outcome.timing!==undefined?`Ejecución: ${h(outcome.timingGrade||'Completada')} · ${n(outcome.chance)}% de probabilidad. `:''}${outcome.success?'Tu intervención se reflejará en el marcador y tus estadísticas.':'La temporada sigue y todavía puede cambiar.'}</small></div>`:selected===null?`<div class="clutch-step-label">1 · ELEGÍ TU DIRECCIÓN</div><div class="clutch-choices">${ZONES.map((z,i)=>`<button data-action="clutch-pick" data-zone="${i}"><span>${h(z)}</span><small>${i===0?'↖':i===1?'↑':'↗'}</small></button>`).join('')}</div>`:meter}<small class="clutch-note">Jugada opcional · Un intento por temporada · La habilidad del futbolista, la dirección y el momento de ejecución influyen. No es un gol garantizado.</small></section>`;
}
function season(){
 const c=getClub(state.clubId),x=state.lastSeason;
 const agenda=getSeasonAgenda(state);
 const decided=state.seasonAgenda?.year===careerYear(state);
 const snapshot=state.careerMoments?.findLast(m=>m.kind==='agenda'&&m.year===careerYear(state));
 const recent=x?[`Última temporada: ${x.matches} partidos, ${x.goals} goles y ${x.assists} asistencias.`, `Tu equipo terminó ${x.leaguePosition}° en ${x.leagueName||'su liga'}.`,`El siguiente campeonato pondrá a prueba tu continuidad en ${c?.name||'el club'}.`]:[`Es tu primera temporada profesional en ${c?.name||'el club'}.`,`Tu primer contrato abre una etapa en la que cada oportunidad importa.`];
 const intro=recent[Math.abs((state.age||17)+(state.history?.length||0))%recent.length];
 const scene=agenda?`<section class="agenda-card"><div class="agenda-overline"><span>EN LA ACTUALIDAD</span><b>${h(agenda.tag)} · ${careerYear(state)}</b></div><h3>${h(agenda.title)}</h3><p>${h(agenda.description)}</p>${decided?`<div class="agenda-result">✓ ${h(snapshot?.choice||'Tu decisión está tomada')} <small>Quedará reflejada en la temporada y en tu historial.</small></div>`:`<div class="agenda-options">${agenda.choices.map((x,i)=>`<button data-action="season-agenda" data-index="${i}"><b>0${i+1}</b><span><strong>${h(x.title)}</strong><small>${h(x.detail)}</small></span><span>↗</span></button>`).join('')}</div>`}<small class="agenda-footnote">Decisión opcional · Puedes simular la temporada sin intervenir.</small></section>`:'';
 const content=`<section class="focus-card stadium season-modern"><div class="focus-eyebrow">TEMPORADA ${careerYear(state)} · ${h(c?.name||'Nuevo desafío')}</div><div class="hero-emblem">${c?badge(c,'hero'):''}</div><div class="spotlight"><span>UN NUEVO CAPÍTULO</span><h2>${x?'La carrera sigue escribiéndose.':'El fútbol te abre la primera puerta.'}</h2><p>${h(intro)}</p>${scene}${seasonMomentPanel()}<div class="season-action-row">${button('SIMULAR TEMPORADA ↗','season-next','main big')}${state.history.length?button('Hablar con mi representante','agent-open','secondary'):''}</div>${x?`<div class="last-match"><strong>ÚLTIMA CAMPAÑA · ${x.year}</strong><span>${x.leaguePosition}° en liga</span><span>${x.matches} PJ</span><span>${x.goals} G</span><span>${x.assists} A</span></div>`:''}</div></section>`;
 return frame(content);
}
function standingsByCup(c,short=true){
 const tables=c.groupTables||[];
 if(!tables.length)return '';
 const target=(state.country&&['qualifiers','international','world-cup'].includes(c.kind))?state.country:state.clubId;
 const visible=short?tables.filter(g=>g.standings?.some(t=>t.id===target)):tables;
 const groups=visible.length?visible:tables.slice(0,1);
 return `<div class="cup-standings">${groups.map(g=>`<div class="cup-group"><b>GRUPO ${h(g.name)}</b><table><thead><tr><th>Equipo</th><th>PJ</th><th>DG</th><th>PTS</th></tr></thead><tbody>${g.standings.map((t,i)=>`<tr class="${t.id===target?'mine':''}"><td>${i+1}. ${h(t.name)}</td><td>${n(t.pj)}</td><td>${t.gd>0?'+':''}${n(t.gd)}</td><td>${n(t.pts)}</td></tr>`).join('')}</tbody></table></div>`).join('')}</div>`;
}
function cupDetail(c){
 const fixtures=c.fixtures||[];
 return `<details class="global-competition-item"><summary><span class="cup-icon">${['international','world-cup','qualifiers'].includes(c.kind)?'🌍':'🏆'}</span><span><b>${h(c.name)}</b><small>${h(c.outcome)} · ${c.played} PJ · ${c.goals} G · ${c.assists} A</small></span><strong>▾</strong></summary><div class="global-fixture-history">${c.qualification?`<small class="cup-qualification">${h(c.qualification)}</small>`:''}${c.format?`<small>${h(c.format)}</small>`:''}${standingsByCup(c)}<h4>Mis partidos</h4>${fixtures.map(f=>`<p><small>${h(f.date||`Ronda ${f.round}`)} · ${h(f.stage)}${f.leg?` · Ida/Vuelta ${f.leg}`:''}</small><span>${h(f.homeName)} <b>${h(f.score)}</b> ${h(f.awayName)}${f.penalties?' · pen.':''}</span>${f.playerPlayed?`<em>${n(f.playerMinutes||0)} min · ${f.playerGoals||0} G · ${f.playerAssists||0} A</em>`:'<em>Sin minutos</em>'}</p>`).join('')||'<p>No disputaste partidos en esta competición.</p>'}</div></details>`;
}
function seasonCalendarPanel(x){
 const events=(x?.competitionCalendar||[]).slice(0,90);
 if(!events.length)return '';
 return `<details class="season-calendar"><summary>📅 Calendario de club y selección · ${events.length} encuentros en copas</summary><div class="season-calendar-matches">${events.map(m=>`<div><small>${h(m.date)}</small><b>${h(m.competition)}</b><span>${h(m.home)} ${h(m.score)} ${h(m.away)}</span><em>${n(m.minutes)} min · ${n(m.goals)} G · ${n(m.assists)} A</em></div>`).join('')}</div><small>Ventanas orientativas, no calendario oficial.</small></details>`;
}
function competitionsPanel(x){
 const items=competitionSummary(x);
 if(!items.length)return '';
 const group=items.filter(c=>c.kind!=='friendly');
 return `<section class="global-competitions"><span class="section-label">COPAS Y SELECCIÓN · ${h(x.year)}</span><div class="global-cups-grid">${group.map(c=>cupDetail(c)).join('')}</div>${x.calledUp?`<p class="global-selection-note">🌎 Convocado por ${h(countryName(state.country))}: ${x.nationalCaps||0} partidos con tu selección.</p>`:'<p class="global-selection-note">La selección todavía no te ha convocado. Tu rendimiento puede cambiarlo.</p>'}${seasonCalendarPanel(x)}</section>`;
}
function endOfYear(){const x=seasonReview(state,getClub);if(!x)return frame('<p>No hay temporada para resumir.</p>');const match=x.match;return frame(`<section class="focus-card story recap"><div class="event-visual"><span class="section-label">FINAL DE TEMPORADA · ${h(x.year)} · ${h(x.league)}</span><h2>Así terminó tu año en ${h(x.club)}</h2><p>Balance de la temporada, con resultados registrados por el simulador.</p></div><div class="story-body"><div class="recap-metrics">${[['Partidos',x.starts],['Goles',x.goals],['Asistencias',x.assists],['Media',x.ovrAfter],['Posición',x.position?x.position+'°':'—']].map(([k,v])=>`<div><b>${h(v)}</b><small>${h(k)}</small></div>`).join('')}</div><div class="recap-summary">${x.summary.map(t=>`<p>• ${h(t)}</p>`).join('')}</div><div class="talk-line"><span class="talk-icon">🎙</span><div><small>${h(x.voice.speaker)} · ${x.voice.fictional?'Titular ficticio de RASCENSO':'Comentario ficticio basado en la temporada'}</small>${x.voice.headline?`<span class="press-headline">${h(x.voice.headline)}</span>`:''}<strong>«${h(x.voice.quote)}»</strong></div></div>${competitionsPanel(state.lastSeason)}${match?`<div class="match-summary-small"><small>PARTIDO DESTACADO · FECHA ${match.round}</small><strong>${h(match.homeName)} ${h(match.score)} ${h(match.awayName)}</strong></div>`:''}${button('Continuar con los acontecimientos →','recap-continue','main wide')}</div></section>`);}
function narrative(){if(state.recapPending)return endOfYear();const e=eventInfo(state);if(!e)return frame('<p>Escena no encontrada.</p>');const x=state.lastSeason;const beat=state.sceneBeat||0,option=e.options[state.sceneChoice??0];const match=matchContext(state,getClub),showGame=['rival','derby','press','coach','title_defense','scouting_competition'].includes(e.id)&&match;const matchDetails=showGame?fixtureContext(state,match,getClub):null;return frame(`<section class="focus-card story"><div class="event-visual"><span class="section-label">${h(e.tag)} · ${h(e.place)}</span><div class="event-illustration">${featureIcon('tactic')}</div><h2>${h(e.title)}</h2><p>${x?`${x.year} · ${x.matches} partidos · ${x.goals} goles · ${x.assists} asistencias`:'Tu primer contrato profesional'}</p></div><div class="story-body">${showGame?`<div class="fixture-feature"><small>${h(matchDetails?.tag||'PARTIDO DESTACADO')} · FECHA ${match.round} · ${h(match.result.toUpperCase())} · ${match.played?match.minutes+' MINUTOS':'SIN MINUTOS'}</small><div>${badge(match.home,'tiny')}<b>${h(match.homeName)}</b><strong>${h(match.score)}</strong><b>${h(match.awayName)}</b>${badge(match.away,'tiny')}</div><p class="match-context-line">Ante ${h(match.opponentName)}: ${match.goals||0} gol(es), ${match.assists||0} asistencia(s). Una escena que sí pertenece a tu temporada.</p></div>`:''}${beat?`<div class="result-card"><span class="section-label">TU DECISIÓN</span><h3>${h(option.title)}</h3><p>${h(option.impact)}</p></div>${button('Continuar carrera →','event-finish','main wide')}`:`<p class="narrative-line">${h(e.paragraphs.join(' '))}</p><div class="talk-line"><span class="talk-icon">⚽</span><div><small>${h(e.speaker.role)}${e.actor==='press'?` · ${h(e.speaker.name)}`:''}</small><strong>${h(e.speech)}</strong></div></div><div class="section-label decision-label">TU DECISIÓN EN EL FÚTBOL</div><div class="football-options">${e.options.map((o,i)=>`<button class="football-choice" data-action="event" data-index="${i}"><span>0${i+1}</span><strong>${h(o.title)}</strong><small>${h(o.detail)}</small><b>↗</b></button>`).join('')}</div><div class="skip-row">${button('Resolver automáticamente','event-skip','ghost')}</div>`}</div></section>`);}
function market(){
 const offers=state.offers||[],policy=state.market||{canStay:true,reason:'normal',searches:0};
 const labels={released:'Tu club decidió no renovarte. Debes encontrar un nuevo equipo.',listed:'La directiva te puso en el mercado. No cuentan contigo para el próximo proyecto.', 'loan-request':'El entrenador prefiere que sumes minutos a préstamo en otro club.',renewal:'Tu contrato está por terminar. Puedes renovar o estudiar otras propuestas.',agent:'Tu representante consultó el mercado por iniciativa tuya.',normal:'Llegaron propuestas de clubes interesados en tu carrera.'};
 const agentMsg=policy.searches>=2?'Ya se realizaron las dos rondas adicionales de búsqueda de esta temporada.':'Pídele a tu representante que explore otros proyectos. Cada búsqueda cambia los clubes interesados.';
 return frame(`<section class="focus-card market"><div class="section-label">MERCADO DE FICHAJES · ${careerYear(state)}</div><h2>${policy.canStay===false?'El club ha tomado una decisión.':'Tu próximo desafío.'}</h2><p class="muted">${h(labels[policy.reason]||labels.normal)} Tu media ${n(state.ovr)}, tus estadísticas, tu edad y la reputación de los clubes condicionan las ofertas.</p><div class="market-summary"><span>MEDIA <b>${n(state.ovr)}</b></span><span>VALORACIÓN DE MERCADO <b>${Math.round(playerDemand(state))}</b></span><span>SUELDO ACTUAL <b>${annualSalaryLabel(state.contract?.salary)}</b></span></div><div class="offers-list">${offers.map((c,i)=>`<div class="offer"><span class="offer-num">0${i+1}</span>${badge(c,'large')}<div class="offer-name"><strong>${h(c.name)} ${c.kind==='loan'?'<span class="market-pill">CESIÓN</span>':''}</strong><small>${flag(c.countryCode)} ${h(c.country)} · ${h(getInauguralLeague(c.id)?.name||'Circuito de referencia')} · Prestigio ${n(c.prestige||clubPrestige(c))}</small><small>${h(c.project||c.role||'Proyecto deportivo')} · ${c.years||3} año(s) · <b>${annualSalaryLabel(c.salary)}</b> al año</small>${c.id===state.fanClubId?'<small class="dream-club">★ Tu equipo de hincha</small>':''}</div>${button(c.kind==='loan'?'Ir cedido ↗':'Firmar ↗','transfer','compact',`data-id="${h(c.id)}"`)}</div>`).join('')||'<div class="market-empty">Por ahora no hay propuestas formales. Tu representante puede consultar nuevamente el mercado.</div>'}</div><div class="agent-panel"><div><strong>📋 TU REPRESENTANTE</strong><p>${h(agentMsg)}</p></div>${button('Buscar otras ofertas','agent-search','secondary',policy.searches>=2?'disabled':'')}</div><div class="market-actions">${policy.canStay===false?'<div class="must-move">El club no te ofrece continuidad esta temporada.</div>':button(policy.renewal?`Renovar · ${annualSalaryLabel(policy.renewal.salary)}/año`:'Seguir en mi club','stay','secondary wide')}${policy.canStay===false&&state.age>=31?button('Retirarme del fútbol','market-retire','ghost'):''}</div><p class="market-disclaimer">Montos orientativos de simulación en euros anuales: no representan contratos oficiales publicados por los clubes.</p></section>`);
}
function academy(){const offers=academyOffers(state);return `<div class="setup-stage"><div class="section-label">CAPÍTULO III · EL PRIMER CONTRATO</div><h1>Tres caminos. <em>Una carrera.</em></h1><p>Estos clubes compiten por tu incorporación. Los primeros pasos son en tu país. Cada institución ofrece un nivel distinto de desafío.</p><div class="academy-dna"><span class="section-label">TU IDENTIDAD</span><strong>${h((state.footballDNA||archetypeFor(state)).name)}</strong><small>${h((state.footballDNA||archetypeFor(state)).bond)} · ${state.draftSources.length} legados elegidos</small></div><div class="academy-grid">${offers.map(c=>`<article class="academy-card">${badge(c,'hero')}<small>${flag(c.countryCode)} ${h(c.country)} · ${h(getInauguralLeague(c.id)?.name||'Circuito de referencia')}</small><h2>${h(c.name)}</h2><p>Nivel institucional <b>${c.level}</b> · ${c.level>=72?'Alta exigencia':c.level>=62?'Proyecto competitivo':'Oportunidad de desarrollo'}</p>${c.id===state.fanClubId?'<span class="fan-hint">★ Tu club de hincha</span>':''}${button('Firmar contrato ↗','academy','main wide',`data-id="${h(c.id)}"`)}</article>`).join('')}</div></div>`;}
function draftScreen(){const picks=draftChoices(state),count=state.draftIndex;const dna=archetypeFor(state);
 return `<div class="setup-stage"><div class="draft-head"><div><span class="section-label">CAPÍTULO VII · TU ADN FUTBOLÍSTICO</span><h1>Elige tu <em>influencia.</em></h1><p>Un ícono, una figura o un profesional. El talento inmediato y el margen de crecimiento no son lo mismo.</p></div><div class="draft-progress"><strong>${count}<span>/8</span></strong><small>DECISIONES</small></div></div><div class="progress-track"><i style="width:${count/8*100}%"></i></div><div class="legend-grid">${picks.map((x,i)=>{const photo=legendPhoto(x.legend),art=legendIllustration(x.legend,x.tier);return `<button class="legend-card has-photo tier-${h(x.tier)}" data-portrait-name="${h(x.legend)}" data-action="draft-accept" data-index="${i}"><div class="legend-photo-backdrop" aria-hidden="true"><img class="legend-illustration" src="${h(art)}" alt="" loading="lazy">${photo?`<img class="legend-real-photo" src="${h(photo)}" alt="" loading="lazy" referrerpolicy="no-referrer" onerror="this.remove()">`:''}</div><div class="legend-card-top"><span>${h(x.tierLabel)}</span><span>${h(x.fit)}</span></div><div class="legend-content"><small>INSPIRADO EN</small><h2>${h(x.legend)}</h2><p>${h(x.tierDetail)}</p><div class="legend-value"><span>${h(x.label.toUpperCase())}</span><strong>${x.hidden?'?':n(x.value)}</strong></div><span class="legend-cta">Incorporar al jugador ↗</span></div></button>`}).join('')}</div><div class="draft-bottom"><div class="draft-collected"><span class="dna-chip">PERFIL: ${h(dna.name)}</span>${ATTRS.map(([k,l])=>`<span class="${k in state.attributes?'found':''}">${h(l)} <b>${k in state.attributes?n(state.attributes[k]):'—'}</b></span>`).join('')}</div>${button(`Cambiar propuestas (${Math.max(0,5-state.draftRerolls)})`,'reroll','secondary',state.draftRerolls>=5?'disabled':'')}</div><p class="photo-credit">Las cifras son evaluaciones ficticias de RASCENSO. Donde no hay fotografía disponible se muestra una ilustración propia, no una imagen real del futbolista. <a href="./assets/MEDIA_CREDITS.html" target="_blank" rel="noopener">Créditos y licencias de fotografías</a>.</p></div>`;
}
function history(){const total=totals(state);return frame(`<section class="focus-card history"><div class="section-label">ARCHIVO DE CARRERA</div><h2>Una historia, temporada a temporada.</h2><div class="history-totals">${[['Temporadas',state.history.length],['Partidos',total.matches],['Goles',total.goals],['Asistencias',total.assists],['Títulos',state.trophies.length]].map(([name,val])=>`<div><strong>${n(val)}</strong><small>${name}</small></div>`).join('')}</div><div class="history-table"><div class="history-head"><span>AÑO · CLUB</span><span>OVR</span><span>PJ</span><span>G</span><span>A</span><span>LIGA</span></div>${[...state.history].reverse().map(x=>`<div class="history-row"><span>${badge(x.clubId)}<span>${x.year} · ${h(short(x.club))}</span></span><b>${x.ovrAfter}</b><b>${x.matches}</b><b>${x.goals}</b><b>${x.assists}</b><b>${x.leaguePosition}°</b></div>`).join('')||'<p class="muted">Todavía no has disputado una temporada.</p>'}</div><div class="history-cups"><h3>Jugadas para recordar</h3><div class="career-highlight-list">${(state.careerMoments||[]).filter(x=>x.kind==='on-field').slice(-12).reverse().map(x=>`<div><b>${h(x.year)}</b><span>${h(x.text)}</span></div>`).join('')||'<p class="muted">Los momentos especiales se irán guardando a medida que juegues.</p>'}</div><h3>Copas y selección por temporada</h3>${[...state.history].reverse().filter(t=>t.competitions?.length).map(t=>`<details><summary><strong>${h(t.year)} · ${h(t.club)}</strong><span>${t.competitions.filter(c=>c.championWon).length} títulos · ${t.nationalCaps||0} PJ selección</span></summary>${t.competitions.map(c=>`<details class="history-competition"><summary><b>${h(c.name)}</b> · ${h(c.outcome)} · ${c.played} PJ · ${c.goals} G</summary><div class="history-fixtures">${(c.playerFixtures||[]).map(f=>`<p>${h(f.stage)} · ${h(f.homeName)} <b>${h(f.score)}</b> ${h(f.awayName)}</p>`).join('')||'<p>Sin partidos registrados.</p>'}</div></details>`).join('')}${seasonCalendarPanel(t)}</details>`).join('')||'<p class="muted">Completa una temporada para desbloquear el registro de copas.</p>'}</div></section>`);}
function world(){const country=getCountry(state.country);return frame(`<section class="focus-card world"><div class="section-label">EL MUNDO DEL FÚTBOL</div><h2>${CATALOG_COUNT} clubes. ${GLOBAL_COUNTRIES} nacionalidades.</h2><p class="muted">Catálogo de referencia de distintas temporadas; no corresponde a participantes oficiales de 2026.</p><div class="world-countries">${COUNTRIES.map(c=>`<button class="country-entry" data-action="country" data-id="${c.code}">${flag(c.code)}<span>${h(c.name)}</span><b>${c.clubs.length}</b></button>`).join('')}</div><section class="global-world-guide"><h3>Competiciones jugables del modo carrera</h3><p>Las copas continentales y de selecciones incorporan grupos, tablas y llaves. Los cupos del Mundial salen de eliminatorias simuladas el año anterior; la convocatoria depende de tu rendimiento.</p><div class="world-competition-names">${Object.entries(NATIONAL_CUPS).map(([conf,name])=>`<span>${h(conf)} · ${h(name)}</span>`).join('')}${Object.entries(CONTINENTAL_CLUB_CUPS).flatMap(([conf,names])=>names.map(name=>`<span>${h(conf)} · ${h(name)}</span>`)).join('')}<span>FIFA · Copa Mundial de la FIFA</span><span>Copas nacionales · ${GLOBAL_COUNTRIES} países</span></div><small>Los torneos usan formatos, cupos y ventanas de calendario simplificados; no equivalen a los reglamentos oficiales.</small></section><section class="world-trophy-reference"><h3>Competiciones históricas</h3><p>Copas reales como referencia visual. Algunas todavía no están habilitadas en la simulación.</p><div class="world-trophy-gallery">${WORLD_TROPHIES.map(t=>`<div><img src="./assets/trophies/real-${t.key}.png" alt="Trofeo de ${h(t.name)}" onerror="this.src=\'./assets/trophies/continental.png\'"><b>${h(t.name)}</b><small>${h(t.region)}</small></div>`).join('')}</div></section><div class="world-spotlight"><strong>${flag(country.code)} ${h(country.name)}</strong><small>${country.clubs.length} clubes de referencia</small></div></section>`);}
function farewell(){
 const record=careerAchievements(state), headline=careerHeadline(state);
 const clubList=record.clubs.slice(0,12).map(c=>`<div class="archive-club">${badge(c.id,'large')}<span><b>${h(c.name)}</b><small>${c.years.length} temporadas · ${c.matches} PJ · ${c.goals} G</small></span><em>${Math.min(...c.years)}–${Math.max(...c.years)}</em></div>`).join('');
 const tiles=record.titles.slice().reverse().slice(0,16).map(t=>`<div class="archive-trophy"><img src="${trophyImage({title:t.name,kind:t.kind})}" onerror="this.src='./assets/trophies/league.png'" alt=""><span>${h(t.name)}</span><small>${h(t.year||'—')}</small></div>`).join('');
 return frame(`<section class="focus-card farewell archive-career"><header class="archive-heading"><div class="section-label">EXPEDIENTE DE CARRERA · ${h(state.country)}</div><h2>${h(headline)}</h2><p>La historia de <strong>${h(state.name)}</strong> · ${record.first||'—'}–${record.last||'—'} · Retiro a los ${state.age} años</p></header><div class="archive-stats">${[['Temporadas',record.seasons],['Partidos',record.matches],['Goles',record.goals],['Asistencias',record.assists],['Títulos',record.titles.length],['Selección',record.caps],['Mejor media',record.peak]].map(([k,v])=>`<div><strong>${n(v)}</strong><small>${k}</small></div>`).join('')}</div><div class="archive-columns"><section><h3>Los clubes de tu vida</h3><div class="archive-clubs">${clubList}</div></section><section><h3>La vitrina de títulos</h3><div class="archive-trophies">${tiles||'<p>Una carrera también se mide por las historias, no solamente por las copas.</p>'}</div><h3>Últimas temporadas</h3><div class="archive-chronology">${state.history.slice(-5).reverse().map(y=>`<p><b>${y.year}</b> · ${h(y.club)} · ${y.matches} PJ · ${y.goals} G · ${y.assists} A</p>`).join('')}</div></section></div><div class="archive-highlights"><h3>Momentos inolvidables</h3>${(state.careerMoments||[]).filter(x=>x.kind==='on-field').slice(-5).reverse().map(x=>`<p><b>${h(x.year)}</b> · ${h(x.text)}</p>`).join('')||'<p>Las temporadas se escribieron dentro y fuera de la cancha.</p>'}</div><div class="archive-buttons">${button('Compartir expediente PNG','share-png','main')}${button('Exportar guardado completo','export','secondary')}${button('Crear otro futbolista','reset','ghost')}</div><small class="archive-footnote">RASCENSO · Una creación de Ragamoofi · Estadísticas de simulación · Sin afiliación oficial a clubes ni federaciones</small></section>`);
}

async function shareCareerPNG(){
 const a=careerAchievements(state),canvas=document.createElement('canvas');canvas.width=1400;canvas.height=1000;
 const ctx=canvas.getContext('2d');if(!ctx)return;
 const drawImage=async (path,x,y,w,h)=>{const img=new Image();img.src=path;try{await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;if(img.complete&&img.naturalWidth)resolve();});ctx.drawImage(img,x,y,w,h);return true;}catch{return false;}};
 ctx.fillStyle='#09172b';ctx.fillRect(0,0,1400,1000);
 const g=ctx.createLinearGradient(0,0,1350,900);g.addColorStop(0,'#174365');g.addColorStop(.62,'#0d263e');g.addColorStop(1,'#07182a');ctx.fillStyle=g;ctx.fillRect(20,20,1360,960);
 ctx.fillStyle='#e9ad75';ctx.fillRect(54,55,6,138);
 await drawImage('./assets/brand/rascenso-icon.png',1240,48,91,91);
 ctx.fillStyle='#e9b782';ctx.font='800 22px sans-serif';ctx.fillText('RASCENSO · DEL BARRIO A LA HISTORIA',82,90);
 ctx.fillStyle='#fff';ctx.font='900 55px sans-serif';ctx.fillText(state.name.slice(0,34),80,158);
 ctx.fillStyle='#c4d7eb';ctx.font='22px sans-serif';ctx.fillText(`${careerHeadline(state)} · ${a.first||'—'}–${a.last||'—'} · retiro a los ${state.age} años`,80,204);
 const stats=[['TEMPORADAS',a.seasons],['PARTIDOS',a.matches],['GOLES',a.goals],['ASISTENCIAS',a.assists],['TÍTULOS',a.titles.length],['SELECCIÓN',a.caps]];
 stats.forEach(([label,val],i)=>{const x=77+i*208;ctx.fillStyle='#23405c';ctx.fillRect(x,247,191,102);ctx.fillStyle='#fff';ctx.font='900 39px sans-serif';ctx.fillText(String(val),x+14,297);ctx.fillStyle='#bbd3ea';ctx.font='13px sans-serif';ctx.fillText(label,x+14,330);});
 ctx.fillStyle='#e9b782';ctx.font='bold 22px sans-serif';ctx.fillText('LOS CLUBES DE MI CARRERA',78,405);
 const list=a.clubs.slice(0,12);
 for(let i=0;i<list.length;i++){
  const cl=list[i],col=i%2,row=Math.floor(i/2),x=78+col*636,y=428+row*55;
  ctx.fillStyle='#233f58';ctx.fillRect(x,y,616,49);
  const hasBadge=await drawImage(`./assets/crests/${encodeURIComponent(cl.id)}.png`,x+7,y+5,39,39);
  if(!hasBadge){ctx.fillStyle='#f0b87b';ctx.font='bold 22px sans-serif';ctx.fillText('⚽',x+12,y+32);}
  ctx.fillStyle='#fff';ctx.font='bold 18px sans-serif';ctx.fillText(cl.name.slice(0,34),x+57,y+21);
  ctx.fillStyle='#bed0e2';ctx.font='13px sans-serif';ctx.fillText(`${Math.min(...cl.years)}–${Math.max(...cl.years)} · ${cl.matches} PJ · ${cl.goals} G`,x+57,y+40);
 }
 ctx.fillStyle='#e9b782';ctx.font='bold 22px sans-serif';ctx.fillText('TÍTULOS Y RECUERDOS',80,805);
 const awards=a.titles.slice(-7).reverse();
 for(let i=0;i<awards.length;i++){
  const t=awards[i],x=81+i*183;
  ctx.fillStyle='#25445e';ctx.fillRect(x,823,171,113);
  const imgSrc=trophyImage({title:t.name,kind:t.kind});
  const loaded=await drawImage(imgSrc,x+60,828,51,58);
  if(!loaded){ctx.font='32px sans-serif';ctx.fillStyle='#f0b87b';ctx.fillText('🏆',x+59,871);}
  ctx.fillStyle='#fff';ctx.font='bold 11px sans-serif';ctx.fillText(String(t.name).slice(0,24),x+9,906);
  ctx.fillStyle='#d0dce9';ctx.font='12px sans-serif';ctx.fillText(String(t.year),x+9,924);
 }
 if(!awards.length){ctx.fillStyle='#d4e6f4';ctx.font='17px sans-serif';ctx.fillText('Cada carrera es una historia, con o sin copas.',82,883);}
 ctx.fillStyle='#89acc8';ctx.font='12px sans-serif';ctx.fillText('Carrera simulada · Proyecto independiente de Ragamoofi · Sin afiliación oficial a clubes o federaciones',77,960);
 const url=canvas.toDataURL('image/png'),anchor=document.createElement('a');anchor.download=`rascenso-expediente-${state.name.normalize('NFD').replace(/[^a-zA-Z0-9]+/g,'-')}.png`;anchor.href=url;anchor.click();
}
function tools(){return `<div class="modal-dimmer" id="modal"><div class="tool-panel"><span class="section-label">GESTIÓN DE CARRERA</span><h2>Tu partida</h2><p>RASCENSO guarda automáticamente en este navegador y conserva un respaldo anterior. Exporta una copia antes de cambiar de dispositivo.</p>${button('Exportar guardado JSON','export','main wide')}${button('Importar guardado JSON','import','secondary wide')}<input type="file" id="import-file" accept="application/json,.json" hidden>${button('Simular hasta el retiro','retire-auto','secondary wide')}${button('Nueva carrera','reset','danger wide')}<p class="credits-note">Créditos de fotografías: <a href="https://commons.wikimedia.org/" target="_blank" rel="noopener">Wikimedia Commons</a>. <a href="./assets/MEDIA_CREDITS.html" target="_blank" rel="noopener">Autores y licencias de cada imagen</a>.</p>${button('Cerrar','tools-close','ghost wide')}</div></div>`;}
function render(){message='';if(!state)return creator();if(state.phase==='draft'){shell(draftScreen());enhanceLegendImages(ROOT);return;}if(state.phase==='academy')return shell(academy());let center=tab==='historial'?history():tab==='mundo'?world():state.phase==='season'?season():state.phase==='event'?narrative():state.phase==='transfer'?market():farewell();shell(center,showNew?tools():'');}
function gather(){document.querySelectorAll('#creation-form [name]').forEach(el=>{if(el.type==='radio'&&!el.checked)return;draft[el.name]=el.value;});}
function begin(){gather();if(!draft.name.trim()){wizard=0;render();document.querySelector('[name="name"]')?.focus();return;}const number=Number(draft.number);if(number<1||number>99){wizard=0;render();return;}try{mutate(newCareer({...draft,seed:`${Date.now()}-${Math.random().toString(36).slice(2)}`}));}catch(e){alert(e.message);}}
function download(){const data=JSON.stringify(state,null,2);const url=URL.createObjectURL(new Blob([data],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`rascenso-${state.name.toLowerCase().replace(/[^a-z0-9]+/g,'-')}-${Date.now()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
ROOT.addEventListener('change',e=>{if(e.target.closest('#creation-form')){gather();if(e.target.name==='country')draft.fanClubId='';render();}if(e.target.id==='import-file'){const file=e.target.files?.[0];if(!file)return;file.text().then(x=>{let data=migrateCareer(JSON.parse(x));if(!data)throw Error('Archivo incompatible');if(!confirm('¿Reemplazar la partida actual por este guardado?'))return;showNew=false;mutate(data);}).catch(err=>alert(`Error al importar: ${err.message}`));}});
ROOT.addEventListener('input',e=>{if(e.target.closest('#creation-form')&&e.target.name)draft[e.target.name]=e.target.value;});
ROOT.addEventListener('submit',e=>{if(e.target.id==='creation-form'){e.preventDefault();wizard===5?begin():((gather(),wizard++,render()));}});
ROOT.addEventListener('click',e=>{
 const a=e.target.closest('[data-action]');if(!a||a.disabled)return;
 const action=a.dataset.action;
 if(action==='step'){gather();wizard=Math.min(wizard,Number(a.dataset.index));render();return;}
 if(action==='creator-prev'){gather();wizard=Math.max(0,wizard-1);render();return;}
 if(action==='creator-next'){gather();if(wizard===0&&!draft.name.trim()){document.querySelector('[name="name"]')?.focus();return;}wizard=Math.min(5,wizard+1);render();return;}
 if(action==='create'){begin();return;}
 if(action==='draft-accept')return mutate(acceptDraft(state,Number(a.dataset.index)));
 if(action==='reroll')return mutate(rerollDraft(state));
 if(action==='academy')return mutate(signAcademy(state,a.dataset.id));
 if(action==='preparation')return mutate(choosePreparation(state,a.dataset.id));
 if(action==='clutch-pick'){if(state.phase!=='season'||state.clutchMoment)return;skillUI.zone=Number(a.dataset.zone);render();skillUI.started=performance.now();return;}
 if(action==='clutch-cancel'){skillUI.zone=null;render();return;}
 if(action==='clutch-stop'){if(skillUI.zone===null||state.phase!=='season'||state.clutchMoment)return;const zone=skillUI.zone,timing=timingAt(performance.now()-skillUI.started);skillUI.zone=null;return mutate(playCareerMoment(state,zone,timing));}
 if(action==='season-agenda')return mutate(chooseSeasonAgenda(state,Number(a.dataset.index))); 
 if(action==='plan')return mutate(chooseSeasonPlan(state,a.dataset.id));
 if(action==='season-next')return mutate(advanceSeason(state));
 if(action==='agent-open')return mutate(openAgentMarket(state));
 if(action==='agent-search')return mutate(askAgentForMore(state));
 if(action==='market-retire')return mutate(retireFromMarket(state));
 if(action==='recap-continue')return mutate({...state,recapPending:false});
 if(action==='event')return mutate(resolveEvent(state,Number(a.dataset.index)));
 if(action==='event-skip')return mutate(autoResolveEvent(state));
 if(action==='event-finish')return mutate(finishEvent(state));
 if(action==='transfer')return mutate(chooseTransfer(state,a.dataset.id));
 if(action==='stay')return mutate(chooseTransfer(state));
 if(action==='right-tab'){rightTab=a.dataset.id==='matches'?'matches':'standings';render();return;}
 if(action==='nav'){tab=a.dataset.tab;render();return;}
 if(action==='tools'){showNew=true;render();return;}
 if(action==='tools-close'){showNew=false;render();return;}
 if(action==='export'){download();return;}
 if(action==='share-png'){shareCareerPNG().catch(err=>alert('No se pudo generar la imagen: '+err.message));return;}
 if(action==='import'){document.getElementById('import-file')?.click();return;}
 if(action==='reset'){if(!confirm('¿Crear una nueva carrera? Exporta la actual antes de reemplazarla.'))return;localStorage.removeItem(STORE);state=null;showNew=false;wizard=0;render();return;}
 if(action==='retire-auto'){if(!confirm('¿Avanzar automáticamente hasta el retiro? No podrás deshacerlo sin un guardado anterior.'))return;showNew=false;mutate(simulateToRetirement(state));return;}
 if(action==='country'){const code=a.dataset.id;document.querySelector('.world-spotlight').innerHTML=`<strong>${flag(code)} ${h(countryName(code))}</strong><small>${getCountry(code).clubs.length} clubes de referencia · ${h(getCountry(code).clubs.slice(0,6).map(x=>x.name).join(' · '))}</small>`;}
});
document.addEventListener?.('keydown',e=>{
 if(e.code==='Space'&&skillUI.zone!==null&&state?.phase==='season'&&tab==='carrera'&&!e.repeat&&!e.target.closest('input,textarea,select')){e.preventDefault();ROOT.querySelector('[data-action="clutch-stop"]')?.click();}
});
ROOT.addEventListener('error',e=>{if(e.target.matches('img.badge-img'))e.target.remove();},true);
render();
